   290  static void printImm(MCInst *MI, SStream *O, int64_t imm, bool positive)
   291  {
   292          if (positive) {
   293                  // always print this number in positive form
   294                  if (MI->csh->syntax == CS_OPT_SYNTAX_MASM) {
   295                          if (imm < 0) {
   296                                  if (MI->op1_size) {
   297                                          switch(MI->op1_size) {
   298                                                  default:
   299                                                          break;
   300                                                  case 1:
   301                                                          imm &= 0xff;
   302                                                          break;
   303                                                  case 2:
   304                                                          imm &= 0xffff;
   305                                                          break;
   306                                                  case 4:
   307                                                          imm &= 0xffffffff;
   308                                                          break;
   309                                          }
   310                                  }
   311
   312                                  if (imm == 0x8000000000000000LL)  // imm == -imm
   313                                          SStream_concat0(O, "8000000000000000h");
   314                                  else if (need_zero_prefix(imm))
   315                                          SStream_concat(O, "0%"PRIx64"h", imm);
   316                                  else
   317                                          SStream_concat(O, "%"PRIx64"h", imm);
   318                          } else {
   319                                  if (imm > HEX_THRESHOLD) {
   320                                          if (need_zero_prefix(imm))
   321                                                  SStream_concat(O, "0%"PRIx64"h", imm);
   322                                          else
   323                                                  SStream_concat(O, "%"PRIx64"h", imm);
   324                                  } else
   325                                          SStream_concat(O, "%"PRIu64, imm);
   326                          }
   327                  } else {        // Intel syntax
   328                          if (imm < 0) {
   329                                  if (MI->op1_size) {
   330                                          switch(MI->op1_size) {
   331                                                  default:
   332                                                          break;
   333                                                  case 1:
   334                                                          imm &= 0xff;
   335                                                          break;
   336                                                  case 2:
   337                                                          imm &= 0xffff;
   338                                                          break;
   339                                                  case 4:
   340                                                          imm &= 0xffffffff;
   341                                                          break;
   342                                          }
   343                                  }
   344
   345                                  SStream_concat(O, "0x%"PRIx64, imm);
   346                          } else {
   347                                  if (imm > HEX_THRESHOLD)
   348                                          SStream_concat(O, "0x%"PRIx64, imm);
   349                                  else
   350                                          SStream_concat(O, "%"PRIu64, imm);
   351                          }
   352                  }
   353          } else {
   354                  if (MI->csh->syntax == CS_OPT_SYNTAX_MASM) {
   355                          if (imm < 0) {
   356                                  if (imm == 0x8000000000000000LL)  // imm == -imm
   357                                          SStream_concat0(O, "8000000000000000h");
   358                                  else if (imm < -HEX_THRESHOLD) {
   359                                          if (need_zero_prefix(imm))
   360                                                  SStream_concat(O, "-0%"PRIx64"h", -imm);
   361                                          else
   362                                                  SStream_concat(O, "-%"PRIx64"h", -imm);
   363                                  } else
   364                                          SStream_concat(O, "-%"PRIu64, -imm);
   365                          } else {
   366                                  if (imm > HEX_THRESHOLD) {
   367                                          if (need_zero_prefix(imm))
   368                                                  SStream_concat(O, "0%"PRIx64"h", imm);
