   376                                  if (imm == 0x8000000000000000LL)  // imm == -imm
   377                                          SStream_concat0(O, "0x8000000000000000");
   378                                  else if (imm < -HEX_THRESHOLD)
   379                                          SStream_concat(O, "-0x%"PRIx64, -imm);
