   465                  SStream_concat0(O, ":");
   466          }
   467
   468          SStream_concat0(O, "[");
   469          set_mem_access(MI, true);
   470          printOperand(MI, Op, O);
   471          SStream_concat0(O, "]");
   472          set_mem_access(MI, false);
