   677  static char *printAliasInstr(MCInst *MI, SStream *OS);
   678  #endif
   679  static void printInstruction(MCInst *MI, SStream *O);
   680
   681  void X86_Intel_printInst(MCInst *MI, SStream *O, void *Info)
   682  {
   683  #ifndef CAPSTONE_DIET
   684          char *mnem;
   685  #endif
   686          x86_reg reg, reg2;
   687          enum cs_ac_type access1, access2;
   688
   689          // perhaps this instruction does not need printer
   690          if (MI->assembly[0]) {
   691                  strncpy(O->buffer, MI->assembly, sizeof(O->buffer));
   692                  return;
   693          }
   694
   695  #ifndef CAPSTONE_DIET
   696          // Try to print any aliases first.
   697          mnem = printAliasInstr(MI, O);
   698          if (mnem)
   699                  cs_mem_free(mnem);
   700          else
   701  #endif
   702          {
   703                  X86_lockrep(MI, O);
   704                  printInstruction(MI, O);
   705          }
   706
   707          reg = X86_insn_reg_intel(MCInst_getOpcode(MI), &access1);
   708          if (MI->csh->detail) {
   709  #ifndef CAPSTONE_DIET
   710                  uint8_t access[6] = {0};
   711  #endif
   712
   713                  // first op can be embedded in the asm by llvm.
   714                  // so we have to add the missing register as the first operand
   715                  if (reg) {
   716                          // shift all the ops right to leave 1st slot for this new register op
   717                          memmove(&(MI->flat_insn->detail->x86.operands[1]), &(MI->flat_insn->detail->x86.operands[0]),
   718                                          sizeof(MI->flat_insn->detail->x86.operands[0]) * (ARR_SIZE(MI->flat_insn->detail->x86.operands) - 1));
   719                          MI->flat_insn->detail->x86.operands[0].type = X86_OP_REG;
   720                          MI->flat_insn->detail->x86.operands[0].reg = reg;
   721                          MI->flat_insn->detail->x86.operands[0].size = MI->csh->regsize_map[reg];
   722                          MI->flat_insn->detail->x86.operands[0].access = access1;
   723                          MI->flat_insn->detail->x86.op_count++;
   724                  } else {
   725                          if (X86_insn_reg_intel2(MCInst_getOpcode(MI), &reg, &access1, &reg2, &access2)) {
   726                                  MI->flat_insn->detail->x86.operands[0].type = X86_OP_REG;
   727                                  MI->flat_insn->detail->x86.operands[0].reg = reg;
   728                                  MI->flat_insn->detail->x86.operands[0].size = MI->csh->regsize_map[reg];
   729                                  MI->flat_insn->detail->x86.operands[0].access = access1;
   730                                  MI->flat_insn->detail->x86.operands[1].type = X86_OP_REG;
   731                                  MI->flat_insn->detail->x86.operands[1].reg = reg2;
   732                                  MI->flat_insn->detail->x86.operands[1].size = MI->csh->regsize_map[reg2];
   733                                  MI->flat_insn->detail->x86.operands[1].access = access2;
   734                                  MI->flat_insn->detail->x86.op_count = 2;
   735                          }
   736                  }
   737
   738  #ifndef CAPSTONE_DIET
   739                  get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
   740                  MI->flat_insn->detail->x86.operands[0].access = access[0];
   741                  MI->flat_insn->detail->x86.operands[1].access = access[1];
   742  #endif
   743          }
   744
   745          if (MI->op1_size == 0 && reg)
   746                  MI->op1_size = MI->csh->regsize_map[reg];
   747  }
